import{_ as e,o as f,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"العطلات الرسمية وساعات العمل في رمضان","description":"العطلات المستحقة للعاملين في القطاع الخاص، وكيف تصلك إعلانات العطلات، وساعات العمل في رمضان، وما ينبغي مراعاته خلال الشهر الفضيل.","frontmatter":{"title":"العطلات الرسمية وساعات العمل في رمضان","description":"العطلات المستحقة للعاملين في القطاع الخاص، وكيف تصلك إعلانات العطلات، وساعات العمل في رمضان، وما ينبغي مراعاته خلال الشهر الفضيل.","lastChecked":"2026-10","sourceCount":5},"headers":[],"relativePath":"ar/guide/holidays-and-ramadan.md","filePath":"ar/guide/holidays-and-ramadan.md"}'),s={name:"ar/guide/holidays-and-ramadan.md"};function t(l,a,n,i,c,h){return f(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="العطلات-الرسمية-وساعات-العمل-في-رمضان" tabindex="-1">العطلات الرسمية وساعات العمل في رمضان <a class="header-anchor" href="#العطلات-الرسمية-وساعات-العمل-في-رمضان" aria-label="Permalink to &quot;العطلات الرسمية وساعات العمل في رمضان&quot;">​</a></h1><p>تتناول هذه الصفحة العطلات مدفوعة الأجر المستحقة للعاملين في القطاع الخاص، وساعات العمل المخفضة في رمضان، وما يراعيه المرء خلال الشهر احترامًا له. وتستند أحكام العطلات وساعات العمل إلى كتاب الجيب للعامل الصادر عن اللجنة الوطنية لحقوق الإنسان في ديسمبر 2021، لذلك تحقق من أي تعديلات لاحقة.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="العطلات-مدفوعة-الأجر-في-القطاع-الخاص" tabindex="-1">العطلات مدفوعة الأجر في القطاع الخاص <a class="header-anchor" href="#العطلات-مدفوعة-الأجر-في-القطاع-الخاص" aria-label="Permalink to &quot;العطلات مدفوعة الأجر في القطاع الخاص&quot;">​</a></h2><p>يذكر الكتاب الأيام التالية إجازات بأجر كامل:<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li>عيد الفطر: ثلاثة أيام.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>عيد الأضحى: ثلاثة أيام.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>اليوم الوطني: يوم واحد، في 18 ديسمبر.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>ثلاثة أيام أخرى يحدد مواعيدها صاحب العمل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li></ul><p>إذا استدعت ظروف العمل تشغيلك في أي من هذه الأيام، وجب تعويضك عنها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="اليوم-الرياضي-للدولة" tabindex="-1">اليوم الرياضي للدولة <a class="header-anchor" href="#اليوم-الرياضي-للدولة" aria-label="Permalink to &quot;اليوم الرياضي للدولة&quot;">​</a></h2><p>أعلن مصرف قطر المركزي في 2024 أن اليوم الرياضي للدولة، الثلاثاء 13 فبراير 2024، عطلة رسمية، على أن تعود المؤسسات المالية إلى العمل في اليوم التالي. راجع إعلان كل عام لمعرفة الموعد، واسأل صاحب العمل إن كانت العطلة تشملك، فهذا اليوم غير مذكور في قائمة الكتاب.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="كيف-تعرف-مواعيد-العطلات" tabindex="-1">كيف تعرف مواعيد العطلات <a class="header-anchor" href="#كيف-تعرف-مواعيد-العطلات" aria-label="Permalink to &quot;كيف تعرف مواعيد العطلات&quot;">​</a></h2><p>ينشر مصرف قطر المركزي إعلاناته الخاصة بالمؤسسات المالية على موقعه، مثل تعميم اليوم الوطني لعام 2024 وإعلان اليوم الرياضي لعام 2024. استخدمها لمعرفة مواعيد إغلاق البنوك.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h2 id="ساعات-العمل-في-رمضان" tabindex="-1">ساعات العمل في رمضان <a class="header-anchor" href="#ساعات-العمل-في-رمضان" aria-label="Permalink to &quot;ساعات العمل في رمضان&quot;">​</a></h2><ul><li>القطاع الخاص: يذكر الكتاب ست ساعات عمل في اليوم خلال رمضان، مع فترة راحة لا تُحسب ضمن ساعات العمل.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>البنوك والمؤسسات المالية: حدد مصرف قطر المركزي لرمضان 2026 (1447 هـ) خمس ساعات في اليوم، من 9:00 صباحًا إلى 2:00 ظهرًا. وقد يتغير ذلك من عام إلى آخر.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li></ul><p>يبدأ شهر رمضان برؤية الهلال ويستمر نحو 29 أو 30 يومًا، لذلك تتغير مواعيده كل عام.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></p><h2 id="خلال-شهر-رمضان" tabindex="-1">خلال شهر رمضان <a class="header-anchor" href="#خلال-شهر-رمضان" aria-label="Permalink to &quot;خلال شهر رمضان&quot;">​</a></h2><p>تقدم قطر للسياحة هذه النصائح للزوار، وهي مفيدة كذلك للمقيمين الجدد.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></p><ul><li>تجنب الأكل أو الشرب أو التدخين في الأماكن العامة خلال ساعات الصيام.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>تجنب الموسيقى الصاخبة والألفاظ المسيئة.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li><li>ارتد ملابس محتشمة في الأماكن العامة. ويُنصح عمومًا بملابس خفيفة تغطي الكتفين والركبتين.<sup class="footnote-ref"><a href="#fn5" id="fnref5:4">[5]</a></sup></li><li>تحقق من المواعيد قبل الخروج، فقد تتغير ساعات عمل المعالم والمطاعم والمتاجر.<sup class="footnote-ref"><a href="#fn5" id="fnref5:5">[5]</a></sup></li><li>إذا لم تكن صائمًا، فإن كثيرًا من الفنادق والمطاعم ومناطق تناول الطعام المخصصة تواصل تقديم الطعام.<sup class="footnote-ref"><a href="#fn5" id="fnref5:6">[5]</a></sup></li></ul><p>انظر أيضًا: <a href="./work-and-labour-rights">العمل وحقوق العمال</a>، <a href="./banking-and-money">البنوك وتحويل الأموال</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>اللجنة الوطنية لحقوق الإنسان، <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">كتاب الجيب للعامل، الطبعة السادسة، ديسمبر 2021</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>مصرف قطر المركزي، <a href="https://www.qcb.gov.qa/en/news/pages/12feb24.aspx" target="_blank" rel="noreferrer">إعلان عطلة اليوم الرياضي للدولة</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>مصرف قطر المركزي، <a href="https://www.qcb.gov.qa/en/News/pages/16dec.aspx" target="_blank" rel="noreferrer">تعميم بمناسبة اليوم الوطني 2024</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>مصرف قطر المركزي، <a href="https://www.qcb.gov.qa/en/News/Pages/ramadan2026.aspx" target="_blank" rel="noreferrer">مواعيد العمل خلال شهر رمضان</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>قطر للسياحة، <a href="https://visitqatar.com/intl-en/about-qatar/traditions/ramadan" target="_blank" rel="noreferrer">تقاليد رمضان في قطر</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',20)])])}const u=e(s,[["render",t]]);export{d as __pageData,u as default};
